import {paintMineralContact,visionPresentationScale} from './cave-field-presentation.js';
import {expandedBossArena,bossArenaArt,bossArenaPavingTransform} from './boss-arena-space.js';
import {CAMPAIGN_CAVE_ART} from './campaign-cave-data.js';
import {isCampaignCave} from './campaign-cave-layout.js';
import {prepareCampaignGeometry} from './campaign-cave-geometry.js';
import {createExpeditionRenderer} from './campaign-cave-surface.js';
import {paintPilotWall,traceBurrowArch} from './campaign-cave-walls.js';
import {paintArenaGround,paintArenaProp,paintArenaCage} from './campaign-cave-arena.js';
import {paintBrazierFlame} from './campaign-cave-flame.js';
import {createTerrainPainter,normalizeTerrainMask,traceTerrainTile,paintTerrainMotion} from './campaign-cave-terrain.js';
import {hedgehogMood} from './hedgehog.js';
const assets=new Map(),scenes=new WeakMap(),nightCanvases=new WeakMap();
const makeCanvas=(w,h)=>{const c=document.createElement('canvas');c.width=w;c.height=h;return c;};
const project=(x,y)=>[50+22*x+2*y,57.5+16*y];
function loadImages(biome){if(assets.has(biome)){const p=assets.get(biome);assets.delete(biome);assets.set(biome,p);return p;}const data=CAMPAIGN_CAVE_ART[biome],promise=Promise.all(Object.entries({...data.assets,'occlusion-mask':'./assets/campaign-caves-v1/occlusion-mask.png'}).map(([key,src])=>new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve([key,im]);im.onerror=()=>reject(Error('Cave asset '+key));im.src=src;}))).then(entries=>new Map(entries));if(assets.size>=2)assets.delete(assets.keys().next().value);assets.set(biome,promise);return promise;}
function population(room){let nodes=[],rocks=[],all=[],byChunk=new Map(),byId=new Map();const sync=()=>{if(nodes===room.nodes&&rocks===room.rocks&&all.length===nodes.length+rocks.length)return;nodes=room.nodes;rocks=room.rocks;all=[...nodes,...rocks];byChunk=new Map();byId=new Map();for(const n of all){byId.set(n.id,n);const key=Math.floor(n.x/16)+','+Math.floor(n.y/16);if(!byChunk.has(key))byChunk.set(key,[]);byChunk.get(key).push(n);}};sync();return {sync,get all(){return all;},get byChunk(){return byChunk;},byId:()=>byId,ledger:{removed:{has:id=>!byId.has(id)||byId.get(id).hp<=0},listChunk:key=>(byChunk.get(key)||[]).filter(n=>n.hp>0)}};}
const windowClip=(c,player)=>{const path=new Path2D();path.rect(-10000,-10000,20000,20000);path.rect(player.x/2-52,player.y/2-80,104,120);c.clip(path,'evenodd');};
export function campaignCaveScene(room,biome){
 if(!isCampaignCave(room))return null;if(scenes.has(room))return scenes.get(room);
 const base=CAMPAIGN_CAVE_ART[biome],data=expandedBossArena(room)?{...base,arena:bossArenaArt(room,base.arena)}:base,pop=population(room),state={room,biome,data,dynamicMineralShadows:true,surface:null,loading:true,error:null,initial:true,view:null,images:null,props:[],newShadows:new Map(),initialIds:new Set([...room.nodes,...room.rocks].map(n=>n.id))};scenes.set(room,state);
 state.promise=Promise.all([loadImages(biome),prepareCampaignGeometry(room)]).then(([images,geometry])=>{
  if(state.disposed)return;state.images=images;if(room.bossFloor)images=new Map(images).set('burrow-host',images.get('boss-burrow-host'));
  const world={...room,rooms:room.layout.rooms},runtime={backgroundRasters:!room.bossFloor,mineralShadows:false,makeCanvas,images,material:data.material,paintPilotWall,traceBurrowArch,createTerrainPainter,normalizeTerrainMask,traceTerrainTile,paintTerrainMotion,population:pop,ledger:pop.ledger};
  state.surface=createExpeditionRenderer(runtime,world,geometry,null);
  state.arrivalGround=new Path2D();const entry=room.layout.spawn||{x:3,y:11};for(let gy=Math.max(1,entry.y-6);gy<=Math.min(room.rows-2,entry.y+3);gy++)for(let gx=Math.max(1,entry.x-8);gx<=Math.min(room.cols-2,entry.x+8);gx++)if(room.floorMask[gy*room.cols+gx]){const [px,py]=project(gx,gy);state.arrivalGround.moveTo(px-12,py-8);state.arrivalGround.lineTo(px+10,py-8);state.arrivalGround.lineTo(px+12,py+8);state.arrivalGround.lineTo(px-10,py+8);state.arrivalGround.closePath();}
  if(room.bossFloor){
   const path=new Path2D();for(let y=1;y<room.rows-1;y++)for(let x=1;x<room.cols-1;x++)if(room.floorMask[y*room.cols+x]){const [px,py]=project(x,y);path.moveTo(px-12,py-8);path.lineTo(px+10,py-8);path.lineTo(px+12,py+8);path.lineTo(px-10,py+8);path.closePath();}
   state.arenaGround=makeCanvas(1200,760);const gc=state.arenaGround.getContext('2d');if(expandedBossArena(room)){const t=bossArenaPavingTransform(room),unbounded=new Path2D();unbounded.rect(-1000,-1000,4000,4000);gc.save();gc.clip(path);gc.transform(t.sx,0,0,t.sy,t.x,t.y);paintArenaGround(gc,{arena:data.arena},unbounded);gc.restore();}else paintArenaGround(gc,{arena:data.arena},path);
   state.props=data.arena.props.map(prop=>{const b=prop.bounds,canvas=makeCanvas(b.w*2,b.h*2),c=canvas.getContext('2d');c.setTransform(2,0,0,2,-b.x*2,-b.y*2);paintArenaProp(c,prop);return {...b,canvas,prop,visualDepth:prop.visualDepth,type:'campaignPillar'};});
  }
 }).catch(error=>{state.error=String(error.message||error);});
 state.prepare=(view,player,heading={x:0,y:0})=>{if(state.disposed||state.error)return false;try{state.view=view;pop.sync();if(!state.surface){state.loading=true;return false;}const stream=state.surface.stream;stream.setView(view,{ahead:heading});const urgent=state.initial||!stream.readyFor(view);stream.pump({budgetMs:urgent?4:2,maxUnits:urgent?128:32});state.loading=state.initial?!stream.warmFor(view):!stream.readyFor(view);if(!state.loading)state.initial=false;return !state.loading;}catch(error){state.error=String(error.message||error);state.loading=true;return false;}};
 state.paintGround=(c,time,soft)=>{if(!state.surface)return;state.surface.paintGround(c,state.view,{time,soft,resources:!room.bossFloor});if(state.arenaGround){c.drawImage(state.arenaGround,0,0);state.surface.paintShadows(c,state.view);}};
 state.walls=()=>state.surface?state.surface.wallEntities(state.view):[];
 state.paintWall=(c,wall,player)=>state.surface.paintWall(c,wall,{x:(player.x-100-(player.y-115)/8)/44,y:(player.y-115)/32},true);
 state.paintPillar=(c,item,player,{time=0,soft=false}={})=>{state.surface.paintWall(c,item,{x:(player.x-100-(player.y-115)/8)/44,y:(player.y-115)/32},true);c.save();if(item.visualDepth>(player.y-115)/32)windowClip(c,player);paintBrazierFlame(c,item.prop.brazier,{time,soft,bossIndex:biome});c.restore();};
 state.paintBurrow=(c,{phase=0,time=0,soft=false}={})=>{if(!state.surface)return;const mood=hedgehogMood(room.hedgehogGrowth,phase,soft),age=phase-(room.hedgehogGrowth?.lastHitBeat??-1e6),frame=mood.state==='sad'?8+Math.min(3,Math.floor(Math.max(0,age)*2)):mood.state==='recover'?12+Math.min(3,Math.floor((age-2)*4)):Math.floor((soft?0:Math.max(0,phase))*4)%8;state.surface.paintBurrow(c,frame);const b=state.surface.burrowData();if(room.bossFloor&&b){c.save();c.clip(b.clip,'evenodd');traceBurrowArch(c,b.plan.cx,b.plan.cy);c.clip();paintArenaCage(c,b.plan);c.restore();}};
 state.paintDisco=(c,face,player,paint)=>{c.save();if(face.visualDepth>(player.y-115)/32)windowClip(c,player);for(const f of face.faces||[])paint(c,f);c.restore();};
 state.dispose=()=>{scenes.delete(room);state.disposed=true;state.surface?.dispose();for(const p of state.props)p.canvas.width=1;if(state.arenaGround)state.arenaGround.width=1;for(const s of state.newShadows.values())s.canvas.width=1;state.newShadows.clear();};
 return state;
}
export function paintCampaignMineral(c,scene,type,x,y,width,kind=0){const im=scene?.images?.get(`${type}-body-${kind}`);if(!im)return false;if(scene.dynamicMineralShadows)paintMineralContact(c,x,y,width);const s=width/100;c.drawImage(im,x-54*s,y-100*s,108*s,118*s);return true;}
function paintNewShadows(c,scene,pop){
 const room=scene.room,view=scene.view;c.save();c.globalCompositeOperation='multiply';
 for(const n of pop.all){if(n.hp<=0||scene.initialIds.has(n.id))continue;const [x,y]=project(n.x,n.y);if(Math.abs(x-view.center[0])>view.width/2+40||Math.abs(y-view.center[1])>view.height/2+50)continue;let shadow=scene.newShadows.get(n.id);if(!shadow){const canvas=makeCanvas(88,92),sc=canvas.getContext('2d'),path=new Path2D(),left=x-22,top=y-38;sc.setTransform(2,0,0,2,-left*2,-top*2);for(let dy=-3;dy<=1;dy++)for(let dx=-2;dx<=2;dx++){const gx=n.x+dx,gy=n.y+dy;if(gx<1||gy<1||gx>=room.cols-1||gy>=room.rows-1||!room.floorMask[gy*room.cols+gx])continue;const [px,py]=project(gx,gy);path.moveTo(px-12,py-8);path.lineTo(px+10,py-8);path.lineTo(px+12,py+8);path.lineTo(px-10,py+8);path.closePath();}sc.clip(path);const width=n.type==='rock'?29+(n.kind||0)*3:n.kind===2?36:30,s=width/100,im=scene.images.get(`${n.type}-shadow-${n.kind||0}`);sc.globalAlpha=.28;if(im)sc.drawImage(im,x-54*s,y-100*s,108*s,118*s);sc.globalAlpha=.30;sc.fillStyle='#111624';sc.beginPath();sc.ellipse(x,y+.25,width*.22,width*.036,0,0,Math.PI*2);sc.fill();shadow={canvas,x:left,y:top};if(scene.newShadows.size>=64){const first=scene.newShadows.keys().next().value;scene.newShadows.get(first).canvas.width=1;scene.newShadows.delete(first);}scene.newShadows.set(n.id,shadow);}c.drawImage(shadow.canvas,shadow.x,shadow.y,44,46);
 }c.restore();
}
export function paintCampaignNight(c,scene,run,player,viewport,{lights=[]}={}){
 let mask=nightCanvases.get(c);if(!mask){mask=makeCanvas(1,1);nightCanvases.set(c,mask);}const w=Math.ceil(viewport.w)+8,h=Math.ceil(viewport.h)+8;if(mask.width!==w)mask.width=w;if(mask.height!==h)mask.height=h;const m=mask.getContext('2d');m.setTransform(1,0,0,1,0,0);m.clearRect(0,0,w,h);m.fillStyle=['#245473','#005a41','#543545','#3f2966','#245473','#543545','#1d3926'][scene.biome];m.fillRect(0,0,w,h);m.globalCompositeOperation='destination-out';
 const hole=(x,y,r,power)=>{const g=m.createRadialGradient(x,y,r*.45,x,y,r);g.addColorStop(0,'rgba(0,0,0,'+power+')');g.addColorStop(.65,'rgba(0,0,0,'+(power*.85)+')');g.addColorStop(1,'rgba(0,0,0,0)');m.fillStyle=g;m.fillRect(x-r,y-r,r*2,r*2);};hole(player.x/2-viewport.x+4,player.y/2-viewport.y-4,95*visionPresentationScale(run),.84);if(run.room.bossFloor)for(const p of scene.data.arena.props)hole(p.brazier.x-viewport.x+4,p.brazier.y-viewport.y-10,38,.78);for(const p of lights.filter(p=>[p.x,p.y,p.revealRadius,p.power].every(Number.isFinite)&&p.revealRadius>0&&p.power>0).slice(0,8))hole(p.x-viewport.x+4,p.y-viewport.y+4,Math.min(36,p.revealRadius),Math.min(.8,p.power));m.globalCompositeOperation='source-over';c.save();c.globalCompositeOperation='multiply';c.globalAlpha*=.90;c.drawImage(mask,viewport.x-4,viewport.y-4);c.restore();
}
